mapper.select:
select vfp.finprod_id as finprodId, vfp.finprod_abbr as finprodAbbr, vfp.finprod_market_id as finprodMarketId, type.type_1 as fundType, vfp.ISSUER as issuer, vfp.ccy as ccyCode, vfp.idate as idate, vfp.CALENDAR_ID as calendarId, vfp.bln_area as blnArea, vfp.trade_market as tradeMarket, vfp.ISSUER as custodian, ext.pur_speed as purSpeed, ext.red_speed as redSpeed, vfp.CAPI_INCOME_FEATURE as capiIncomeFeature, rule.pay_cycle as payCycle, '' as payDate,
rule.END_TDAY_RULE endTdayRule, rule.PAY_TDAY_RULE payTdayRule, rule.CALC_RULE as calcRule from FIN_PRODUCT vfp left join FIN_PRODUCT_TYPE type on vfp.finprod_id = type.finprod_id left join fin_CASH_PAY_RULE rule on vfp.finprod_id = rule.finprod_id left join FIN_PRODUCT_ADD ext on vfp.finprod_id = ext.finprod_id left join MST_TRADE_CALENDAR mtc on vfp.calendar_id=mtc.trade_calendar_id left join MST_CALENDAR_INFO mci on mtc.calendar_id=mci.calendar_id
AND vfp.finprod_type = #{finprodType}
AND ( vfp.finprod_abbr like concat_ws('','%',#{search},'%') OR vfp.finprod_id like concat_ws('','%',#{search},'%') )
AND vfp.finprod_id in
#{item}
AND type.type_1 in
#{item}
AND vfp.issuer like concat_ws('','%',#{issuer},'%')
